#!/usr/bin/env python3
"""Remove all identification statutes from repo/cli/main.go"""
import re

filepath = '/workspaces/semio/repo/cli/main.go'

with open(filepath, 'r') as f:
    lines = f.readlines()

ID_CODES = [
    'BreachCodeFileMissingIdentification',
    'BreachCodeFileWrongIdentificationId',
    'BreachCodeFileWrongIdentificationUri',
    'BreachCodeSectionMissingIdentification',
    'BreachCodeSectionWrongIdentificationId',
    'BreachCodeSectionWrongIdentificationUri',
    'BreachCodeDefMissingIdentification',
    'BreachCodeDefWrongIdentificationId',
    'BreachCodeDefWrongIdentificationUri',
]

to_remove = set()

# 1. Remove constant definitions
for i, line in enumerate(lines):
    s = line.strip()
    for code in ID_CODES:
        if s.startswith(code) and 'Statute = ' in s:
            to_remove.add(i)
            break

# 2. Remove metadata map entries (multi-line blocks)
i = 0
while i < len(lines):
    s = lines[i].strip()
    for code in ID_CODES:
        if s.startswith(code + ':') and s.endswith('{'):
            j = i + 1
            while j < len(lines):
                if lines[j].strip().startswith('},'):
                    break
                j += 1
            for k in range(i, j + 1):
                to_remove.add(k)
            i = j
            break
    i += 1

# 3. Remove from Territory groups - lines referencing identification statutes
for i, line in enumerate(lines):
    s = line.strip().rstrip(',')
    for code in ID_CODES:
        if s == code:
            to_remove.add(i)
            break

# 4. Remove "Wrong Identification" Territory groups (multi-line blocks)
i = 0
while i < len(lines):
    if 'Name:' in lines[i] and '"Wrong Identification"' in lines[i]:
        # Find the opening { of this Territory
        j = i - 1
        while j >= 0 and '{' not in lines[j]:
            j -= 1
        # Find the closing },
        brace_depth = 0
        k = j
        while k < len(lines):
            brace_depth += lines[k].count('{') - lines[k].count('}')
            if brace_depth <= 0:
                break
            k += 1
        for idx in range(j, k + 1):
            to_remove.add(idx)
        i = k + 1
    else:
        i += 1

# 5. Remove file identification checking code
# Find the block from "expectedFileId := FileHeaderId" to "}" before "contributorPattern"
for i, line in enumerate(lines):
    if 'expectedFileId := FileHeaderId(file)' in line:
        # Find the end - the "}" that closes the else block, right before contributorPattern
        j = i
        brace_depth = 0
        found_if = False
        while j < len(lines):
            if 'contributorPattern' in lines[j]:
                # Go back to find the actual end of the identification block
                break
            j += 1
        # Remove from expectedFileId line to the line before contributorPattern
        for k in range(i, j):
            to_remove.add(k)
        break

# 6. Remove section identification checking code
# Find the block from "hasIdentification := false" after section checking to the identification breach block
for i, line in enumerate(lines):
    s = line.strip()
    if s == 'hasIdentification := false' and i > 17800:  # After file checking
        # This is in the section checking code
        # Find the lines: hasIdentification, identificationLine, identifiedID, identifiedURI
        # Also need to find the breach creation block and remove it

        # Remove the 4 variable declarations
        to_remove.add(i)  # hasIdentification := false
        # identificationLine should be nearby
        for scan in range(max(0, i-5), i+5):
